can you write unit tests for this? using jest, trying to cover the empty cart and the coupon expired cases too

export function applyCoupon(cart, coupon, now = new Date()) {
  if (!coupon || coupon.expiresAt < now) return cart.total;
  return Math.max(0, cart.total - coupon.amount);
}

